function qvSnap(P,C,s){let j=0,bd=1e18;for(let i=0;i<P.length;i++){const d=Math.abs(C[i]-s);if(d<bd){bd=d;j=i}}const a=P[j],b=P[Math.min(P.length-1,j+1)],c=P[Math.max(0,j-1)];return{x:a[0],z:a[1],h:Math.atan2((b[0]-c[0])||1e-6,b[1]-c[1]),j}}
