  if(!R2.P){R2.P=qvPath(R2.x,R2.z,S.x,S.z);R2.C=qvCum(R2.P);R2.s=0}const Lr=R2.C[R2.C.length-1],N=QV.nav,Sp=st[V.si],pf=V.si+(N&&N.rem!=null&&Sp?clamp(1-N.rem/Math.max(60,(Sp.d||300)/1.2),0,1):0);R2.gap=R2.si+R2.s/Math.max(1,Lr)-pf;
