  m.style.cssText=`position:absolute;left:${clamp(cx-r.left,8,Math.max(8,r.width-230))}px;top:${clamp(cy-r.top,8,Math.max(8,r.height-120))}px;z-index:8;display:grid;gap:6px;padding:8px;border-radius:10px;background:rgba(5,11,24,.95);border:1px solid #ff3b5c;min-width:200px;box-shadow:0 4px 0 rgba(0,0,0,.3)`;
